<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure SponsorConnect</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
            background-color: #f7f7f7;
        }
        .container {
            padding: 20px;
            max-width: 800px;
            margin: auto;
            background: white;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
        }
        h1 {
            color: #333;
        }
        label {
            display: block;
            margin: 10px 0 5px;
            font-weight: bold;
        }
        input, select, textarea {
            width: 100%;
            padding: 8px;
            margin-bottom: 10px;
            border: 1px solid #ccc;
            border-radius: 4px;
        }
        button {
            background-color: #28a745;
            color: white;
            padding: 10px 15px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        button:disabled {
            background-color: #ccc;
        }
        .hidden {
            display: none;
        }
        .footer {
            text-align: center;
            padding: 10px;
            font-size: 12px;
            color: #666;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Sponsor Disability Claim Submission</h1>
        <form id="claim-form">
            <label for="policy-number">Policy Number:</label>
            <input type="text" id="policy-number" required>

            <label for="member-id">Member ID:</label>
            <input type="text" id="member-id" required>

            <button type="button" id="lookup-member">Look up member</button>

            <div id="member-details" class="hidden">
                <h2>Member Details</h2>
                <div id="member-name"></div>
                <div id="last-sign-in"></div>
            </div>

            <h3>Claim Details</h3>
            <label for="last-day-worked">Last Day Worked:</label>
            <input type="date" id="last-day-worked" required>

            <label for="first-day-absent">First Day Absent:</label>
            <input type="date" id="first-day-absent" required>

            <label for="nature-of-absence">Nature of Absence:</label>
            <select id="nature-of-absence" required>
                <option value="">--Select--</option>
                <option value="Sick Leave">Sick Leave</option>
                <option value="Medical Leave">Medical Leave</option>
                <option value="Personal Leave">Personal Leave</option>
            </select>

            <label for="absence-details">Details:</label>
            <textarea id="absence-details" rows="4"></textarea>

            <label for="documents">Upload Documents:</label>
            <input type="file" id="documents" multiple>

            <div id="file-list"></div>

            <button type="submit">Submit Claim</button>
        </form>

        <div id="confirmation" class="hidden">
            <h2>Claim Submitted</h2>
            <p>Reference Number: <span id="ref-number"></span></p>
            <p>Status: Received</p>
        </div>
    </div>
    <div class="footer">MapleSure Insurance — fictional demo application</div>

    <script>
        const mockMemberData = {
            "12345": {
                name: "John Doe",
                lastSignIn: "2023-09-28T10:30:00"
            },
            "67890": {
                name: "Jane Smith",
                lastSignIn: "2023-10-01T14:15:00"
            }
        };

        document.getElementById('lookup-member').addEventListener('click', function() {
            const memberId = document.getElementById('member-id').value;
            const detailsDiv = document.getElementById('member-details');
            const nameDiv = document.getElementById('member-name');
            const lastSignInDiv = document.getElementById('last-sign-in');

            if (mockMemberData[memberId]) {
                const member = mockMemberData[memberId];
                nameDiv.innerText = `Name: ${member.name}`;
                lastSignInDiv.innerText = `Last Sign-In: ${new Date(member.lastSignIn).toLocaleString()}`;
                detailsDiv.classList.remove('hidden');
            } else {
                alert('Member not found');
                detailsDiv.classList.add('hidden');
            }
        });

        document.getElementById('documents').addEventListener('change', function(event) {
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            Array.from(event.target.files).forEach(file => {
                const listItem = document.createElement('div');
                listItem.innerText = file.name;
                fileList.appendChild(listItem);
            });
        });

        document.getElementById('claim-form').addEventListener('submit', function(event) {
            event.preventDefault();
            const refNumber = `MS-${new Date().getUTCFullYear()}-08-${Math.floor(1000 + Math.random() * 9000)}`;
            document.getElementById('ref-number').innerText = refNumber;
            document.getElementById('claim-form').classList.add('hidden');
            document.getElementById('confirmation').classList.remove('hidden');
        });
    </script>
</body>
</html>
"}]}
